<template>
  <div class="discussions-page">
    <header class="page-header"><div><h1>讨论与研究</h1><p>和研究助手一起把灵感聊清楚；系统自动沉淀标题、主题、结论与待验证问题。</p></div><el-button type="primary" :icon="Plus" @click="startConversation">新建对话</el-button></header>
    <section class="workspace" v-loading="loading">
      <aside class="conversation-list"><div class="list-tools"><el-input v-model="query" clearable placeholder="搜索讨论" @change="loadList" /><el-button :icon="Refresh" circle @click="loadList" /></div><button v-for="item in discussions" :key="item.id" class="conversation-item" :class="{ selected: selectedId === item.id }" @click="select(item.id)"><strong>{{ item.title }}</strong><p>{{ item.summary || item.question || '从一段想法开始…' }}</p><footer><el-tag size="small" effect="plain" :type="statusType(item.status)">{{ statusLabel(item.status) }}</el-tag><time>{{ formatDate(item.updated_at) }}</time></footer></button><el-empty v-if="!discussions.length && !loading" description="还没有对话" :image-size="66"><el-button type="primary" @click="startConversation">开始第一段讨论</el-button></el-empty></aside>
      <main class="chat-panel"><el-skeleton v-if="detailLoading" :rows="10" animated /><section v-else-if="!selected" class="welcome"><el-icon><ChatDotRound /></el-icon><h2>从一个灵感或疑问开始</h2><p>例如：我想研究智能体如何把零散对话变成可持续推进的项目。</p><el-button type="primary" @click="startConversation">开始对话</el-button></section><template v-else><header class="chat-header"><div><span>研究助手 · 擎天柱</span><h2>{{ selected.title }}</h2></div><el-tag :type="statusType(selected.status)">{{ statusLabel(selected.status) }}</el-tag></header><div ref="messageBox" class="messages"><section v-if="!selected.messages?.length" class="conversation-starter"><h3>这是一段新的讨论</h3><p>直接描述你的灵感、困惑或想验证的判断。AI 会和你一起追问、梳理并生成研究线索。</p></section><article v-for="message in selected.messages" :key="message.id" class="message" :class="message.role"><div class="avatar">{{ message.role === 'user' ? '你' : 'AI' }}</div><div class="bubble"><div class="role">{{ message.role === 'user' ? '你' : '研究助手' }}</div><div class="message-content">{{ message.content }}</div></div></article><article v-if="sending" class="message assistant"><div class="avatar">AI</div><div class="bubble"><div class="role">研究助手</div><el-skeleton :rows="2" animated /></div></article></div><footer class="composer"><el-input v-model="messageInput" type="textarea" :autosize="{ minRows: 2, maxRows: 5 }" placeholder="输入你的想法…（Enter 发送，Shift + Enter 换行）" :disabled="sending" @keydown.enter.exact.prevent="send" /><div><span>对话会自动整理；确认后再保存到 Obsidian。</span><el-button type="primary" :loading="sending" :disabled="!messageInput.trim()" @click="send">发送</el-button></div></footer></template></main>
      <aside class="insight-panel"><template v-if="selected"><header><div><span class="eyebrow">AI 自动沉淀</span><h2>讨论摘要</h2></div><el-button text @click="editing = !editing">{{ editing ? '完成' : '编辑' }}</el-button></header><el-form v-if="editing" label-position="top" class="summary-form"><el-form-item label="标题"><el-input v-model="summaryDraft.title" /></el-form-item><el-form-item label="主题（逗号分隔）"><el-input v-model="summaryDraft.topics" /></el-form-item><el-form-item label="核心问题"><el-input v-model="summaryDraft.question" type="textarea" :rows="2" /></el-form-item><el-form-item label="当前结论"><el-input v-model="summaryDraft.current_conclusion" type="textarea" :rows="2" /></el-form-item><el-form-item label="待验证问题（每行一条）"><el-input v-model="summaryDraft.open_questions" type="textarea" :rows="3" /></el-form-item><el-button type="primary" :loading="saving" @click="saveSummary">保存修改</el-button></el-form><section v-else class="insights"><article><h3>标题</h3><p>{{ selected.title }}</p></article><article><h3>主题</h3><div class="topic-list"><span v-for="topic in selected.topics" :key="topic">#{{ topic }}</span><em v-if="!selected.topics.length">对话后自动生成</em></div></article><article><h3>摘要</h3><p>{{ selected.summary || '继续对话后，AI 会在这里提炼摘要。' }}</p></article><article><h3>核心问题</h3><p>{{ selected.question || '尚未形成明确问题。' }}</p></article><article><h3>当前结论</h3><p>{{ selected.current_conclusion || '仍在探索中。' }}</p></article><article><h3>待验证问题</h3><ul v-if="selected.open_questions.length"><li v-for="item in selected.open_questions" :key="item">{{ item }}</li></ul><p v-else>继续讨论，AI 会补充需要验证的问题。</p></article></section><footer class="insight-actions"><el-button :loading="saving" @click="archive">{{ selected.content_available ? '更新 Obsidian 笔记' : '保存到 Obsidian' }}</el-button><el-button v-if="selected.status !== 'promoted'" type="primary" :disabled="!selected.messages?.length" @click="openPromote">转为研究项目</el-button><el-button v-else type="success" plain @click="router.push('/projects')">查看研究项目</el-button></footer><p v-if="selected.content_available" class="archive-status">已保存：{{ selected.vault_path }}</p></template><section v-else class="summary-empty"><el-icon><DocumentChecked /></el-icon><p>对话中的结构化摘要会显示在这里。</p></section></aside>
    </section>
    <el-dialog v-model="promoteVisible" title="转为研究项目" width="min(560px, 94vw)"><p class="dialog-intro">系统会先将完整对话和摘要保存到 Obsidian，再创建可追溯的“问题界定”研究项目。</p><el-form label-position="top"><el-form-item label="项目名称"><el-input v-model="promotion.project_name" /></el-form-item><el-form-item label="初始假设"><el-input v-model="promotion.hypothesis" type="textarea" :rows="3" /></el-form-item><el-form-item label="项目说明"><el-input v-model="promotion.description" type="textarea" :rows="3" /></el-form-item></el-form><template #footer><el-button @click="promoteVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="promote">创建研究项目</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ChatDotRound, DocumentChecked, Plus, Refresh } from '@element-plus/icons-vue'
import { archiveDiscussion, createConversation, getDiscussion, listDiscussions, promoteDiscussion, sendDiscussionMessage, updateDiscussion, type Discussion } from '@/api/discussions'
const router = useRouter()
const discussions = ref<Discussion[]>([]), selected = ref<Discussion | null>(null), selectedId = ref('')
const loading = ref(false), detailLoading = ref(false), sending = ref(false), saving = ref(false), editing = ref(false), promoteVisible = ref(false)
const query = ref(''), messageInput = ref(''), messageBox = ref<HTMLElement>()
const promotion = ref({ project_name: '', hypothesis: '', description: '' })
const summaryDraft = ref({ title: '', topics: '', question: '', current_conclusion: '', open_questions: '' })
const split = (value: string) => value.split(/[,，\n]/).map(item => item.trim()).filter(Boolean)
const formatDate = (value: string) => value ? new Date(value).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' }) : '-'
const statusLabel = (value: string) => ({ captured: '已记录', exploring: '探索中', research_candidate: '研究候选', promoted: '已转项目', closed: '已关闭' }[value] || value)
const statusType = (value: string) => ({ captured: 'info', exploring: 'warning', research_candidate: 'primary', promoted: 'success', closed: 'info' } as Record<string, any>)[value] || 'info'
function loadDraft(item: Discussion) { summaryDraft.value = { title: item.title, topics: item.topics.join(', '), question: item.question, current_conclusion: item.current_conclusion, open_questions: item.open_questions.join('\n') } }
async function scrollMessages() { await nextTick(); if (messageBox.value) messageBox.value.scrollTop = messageBox.value.scrollHeight }
async function loadList() { loading.value = true; try { discussions.value = (await listDiscussions({ q: query.value })).items } finally { loading.value = false } }
async function select(id: string) { selectedId.value = id; detailLoading.value = true; editing.value = false; try { selected.value = await getDiscussion(id); loadDraft(selected.value); await scrollMessages() } finally { detailLoading.value = false } }
async function startConversation() { saving.value = true; try { const item = await createConversation(); await loadList(); await select(item.id); ElMessage.success('新的讨论已准备好') } finally { saving.value = false } }
async function send() { const content = messageInput.value.trim(); if (!content) return; if (!selected.value) return startConversation(); sending.value = true; messageInput.value = ''; try { selected.value = await sendDiscussionMessage(selected.value.id, content); loadDraft(selected.value); await loadList(); await scrollMessages() } catch (error: any) { messageInput.value = content; ElMessage.error(error?.response?.data?.detail || '研究助手暂时未能回复') } finally { sending.value = false } }
async function saveSummary() { if (!selected.value || !summaryDraft.value.title.trim()) return ElMessage.warning('标题不能为空'); saving.value = true; try { selected.value = await updateDiscussion(selected.value.id, { title: summaryDraft.value.title, topics: split(summaryDraft.value.topics), question: summaryDraft.value.question, current_conclusion: summaryDraft.value.current_conclusion, open_questions: split(summaryDraft.value.open_questions) }); editing.value = false; await loadList(); ElMessage.success('摘要已更新') } finally { saving.value = false } }
async function archive() { if (!selected.value) return; saving.value = true; try { selected.value = await archiveDiscussion(selected.value.id); await loadList(); ElMessage.success('完整对话已保存到 Obsidian') } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '保存失败') } finally { saving.value = false } }
function openPromote() { if (!selected.value) return; promotion.value = { project_name: selected.value.title, hypothesis: selected.value.hypothesis || selected.value.current_conclusion, description: selected.value.question || selected.value.summary }; promoteVisible.value = true }
async function promote() { if (!selected.value) return; saving.value = true; try { if (!selected.value.content_available) selected.value = await archiveDiscussion(selected.value.id); const result = await promoteDiscussion(selected.value.id, promotion.value); promoteVisible.value = false; await loadList(); await select(result.discussion.id); ElMessage.success(result.reused ? '已关联既有研究项目' : '研究项目已创建') } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '创建项目失败') } finally { saving.value = false } }
onMounted(loadList)
</script>

<style scoped>
.discussions-page{max-width:1640px;margin:0 auto;color:var(--text-primary)}.page-header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px}.page-header h1{margin:0;font-size:24px}.page-header p,.archive-status{margin:6px 0 0;color:var(--text-secondary)}.workspace{display:grid;grid-template-columns:270px minmax(420px,1fr) 330px;min-height:720px;border:1px solid var(--line-color);border-radius:8px;overflow:hidden;background:var(--panel-bg)}.conversation-list,.insight-panel{overflow-y:auto}.conversation-list{border-right:1px solid var(--line-color)}.list-tools{display:flex;gap:8px;padding:12px;border-bottom:1px solid var(--line-color)}.conversation-item{display:block;width:100%;padding:14px;border:0;border-bottom:1px solid var(--line-color);background:transparent;color:var(--text-primary);text-align:left;cursor:pointer}.conversation-item.selected{background:var(--view-color-soft);box-shadow:inset 3px 0 0 var(--view-color)}.conversation-item p{margin:7px 0;color:var(--text-secondary);font-size:13px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.conversation-item footer{display:flex;justify-content:space-between;align-items:center;color:var(--text-secondary);font-size:12px}.chat-panel{display:flex;flex-direction:column;min-width:0;background:var(--card-bg-soft)}.chat-header,.insight-panel>header{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;border-bottom:1px solid var(--line-color);background:var(--panel-bg)}.chat-header span,.eyebrow,.role{color:var(--text-secondary);font-size:12px}.chat-header h2,.insight-panel h2{margin:3px 0 0;font-size:18px}.messages{flex:1;padding:22px;overflow-y:auto}.message{display:flex;align-items:flex-start;gap:10px;max-width:88%;margin:0 0 18px}.message.user{margin-left:auto;flex-direction:row-reverse}.avatar{flex:0 0 30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--view-color);color:#fff;font-size:12px}.user .avatar{background:#64748b}.bubble{min-width:0;padding:10px 13px;border:1px solid var(--line-color);border-radius:8px;background:var(--panel-bg)}.user .bubble{background:var(--view-color-soft)}.role{margin-bottom:5px}.message-content{white-space:pre-wrap;word-break:break-word;line-height:1.65}.conversation-starter,.welcome,.summary-empty{color:var(--text-secondary);text-align:center;padding:60px 24px}.conversation-starter h3,.welcome h2{color:var(--text-primary)}.welcome{margin:auto}.welcome .el-icon,.summary-empty .el-icon{font-size:42px;color:var(--view-color)}.composer{padding:14px 18px;border-top:1px solid var(--line-color);background:var(--panel-bg)}.composer>div{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:8px;color:var(--text-secondary);font-size:12px}.insight-panel{border-left:1px solid var(--line-color);background:var(--panel-bg)}.insights{padding:0 18px}.insights article{padding:14px 0;border-bottom:1px solid var(--line-color)}.insights h3{margin:0 0 7px;font-size:13px}.insights p,.insights li{margin:0;white-space:pre-wrap;color:var(--text-secondary);line-height:1.55;font-size:13px}.insights ul{margin:0;padding-left:18px}.topic-list{display:flex;flex-wrap:wrap;gap:6px;color:var(--view-color);font-size:13px}.topic-list em{color:var(--text-secondary);font-style:normal}.summary-form{padding:16px 18px}.insight-actions{display:grid;gap:8px;padding:18px}.archive-status{padding:0 18px 18px;font-size:12px;word-break:break-all}.dialog-intro{color:var(--text-secondary);line-height:1.6}@media(max-width:1100px){.workspace{grid-template-columns:250px minmax(0,1fr)}.insight-panel{grid-column:1/-1;max-height:460px;border-left:0;border-top:1px solid var(--line-color)}.insights{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}}@media(max-width:720px){.page-header{align-items:flex-start;flex-direction:column}.workspace{grid-template-columns:1fr}.conversation-list{max-height:280px;border-right:0;border-bottom:1px solid var(--line-color)}.chat-panel{min-height:620px}.message{max-width:96%}.composer>div span{display:none}.insights{grid-template-columns:1fr}}
</style>
